package com.safebox.self_storage.controller;
import com.safebox.self_storage.dto.support.*; import com.safebox.self_storage.service.SupportRequestService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/support") public class SupportRequestController { private final SupportRequestService s; public SupportRequestController(SupportRequestService s){this.s=s;} @PostMapping public ResponseEntity<SupportRequestView> create(@Valid @RequestBody CreateSupportRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));} @GetMapping("/mine") public List<SupportRequestView> mine(){return s.mine();} @GetMapping("/queue") public List<SupportRequestView> queue(){return s.queue();} @GetMapping("/{id}") public SupportRequestView detail(@PathVariable UUID id){return s.detail(id);} @PutMapping("/{id}/assignment") public SupportRequestView assign(@PathVariable UUID id,@Valid @RequestBody AssignSupportRequest r){return s.assign(id,r);} @PutMapping("/{id}/status") public SupportRequestView status(@PathVariable UUID id,@Valid @RequestBody UpdateSupportStatus r){return s.status(id,r);} @PostMapping("/{id}/messages") public SupportRequestView reply(@PathVariable UUID id,@Valid @RequestBody AddSupportMessage r){return s.reply(id,r);} }
